import{_ as e,o,c as a,a2 as r}from"./chunks/framework.DQhM5RF8.js";const p=JSON.parse('{"title":"How to Join LlamaCraft","description":"","frontmatter":{},"headers":[],"relativePath":"info/how-to-join.md","filePath":"info/how-to-join.md"}'),n={name:"info/how-to-join.md"};function l(i,t,d,c,s,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-join-llamacraft" tabindex="-1">How to Join LlamaCraft <a class="header-anchor" href="#how-to-join-llamacraft" aria-label="Permalink to &quot;How to Join LlamaCraft&quot;">​</a></h1><p>You can play on LlamaCraft using almost any device that runs Minecraft!</p><hr><h2 id="server-connection-addresses-playit-gg" tabindex="-1">Server Connection Addresses (Playit.gg) <a class="header-anchor" href="#server-connection-addresses-playit-gg" aria-label="Permalink to &quot;Server Connection Addresses (Playit.gg)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Server Address (IP)</th><th style="text-align:left;">Port</th><th style="text-align:left;">Supported Versions</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Java Edition (PC / Mac / Linux)</strong></td><td style="text-align:left;"><code>approaching-icc.tun.ply.gg</code></td><td style="text-align:left;"><code>9256</code></td><td style="text-align:left;"><code>1.20</code> - <code>1.21</code></td></tr><tr><td style="text-align:left;"><strong>Bedrock (Phone, iPad, Windows)</strong></td><td style="text-align:left;"><code>approaching-icc.tun.ply.gg</code></td><td style="text-align:left;"><code>9256</code></td><td style="text-align:left;">Latest Bedrock</td></tr><tr><td style="text-align:left;"><strong>Consoles (Xbox, PlayStation, Switch)</strong></td><td style="text-align:left;">Via ScholarCraft, Bedrock DNS, or App</td><td style="text-align:left;"><code>9256</code></td><td style="text-align:left;">Latest Bedrock</td></tr><tr><td style="text-align:left;"><strong>Home Wi-Fi (Local LAN Only)</strong></td><td style="text-align:left;"><code>192.168.0.176</code></td><td style="text-align:left;">Java: <code>25565</code><br>Bedrock: <code>19132</code></td><td style="text-align:left;">Any</td></tr></tbody></table><hr><h2 id="_1-java-edition-pc-mac" tabindex="-1">1. Java Edition (PC &amp; Mac) <a class="header-anchor" href="#_1-java-edition-pc-mac" aria-label="Permalink to &quot;1. Java Edition (PC &amp; Mac)&quot;">​</a></h2><ol><li>Open Minecraft Java Edition (<code>1.20</code> or <code>1.21</code>).</li><li>Click <strong>Multiplayer</strong> then <strong>Add Server</strong>.</li><li>Put <code>LlamaCraft</code> as the Server Name.</li><li>Type <code>approaching-icc.tun.ply.gg:9256</code> as the Server Address.</li><li>Click <strong>Done</strong> and double-click to join!</li></ol><hr><h2 id="_2-bedrock-phone-ipad-tablet-windows-10-11" tabindex="-1">2. Bedrock (Phone, iPad, Tablet, Windows 10/11) <a class="header-anchor" href="#_2-bedrock-phone-ipad-tablet-windows-10-11" aria-label="Permalink to &quot;2. Bedrock (Phone, iPad, Tablet, Windows 10/11)&quot;">​</a></h2><h3 id="method-a-direct-playit-ip" tabindex="-1">Method A: Direct Playit IP <a class="header-anchor" href="#method-a-direct-playit-ip" aria-label="Permalink to &quot;Method A: Direct Playit IP&quot;">​</a></h3><ol><li>Open Minecraft on your phone, iPad, or computer.</li><li>Click <strong>Play</strong> and tap the <strong>Servers</strong> tab at the top.</li><li>Scroll down and tap <strong>Add Server</strong>.</li><li>Fill in: <ul><li><strong>Server Name</strong>: <code>LlamaCraft</code></li><li><strong>Server Address</strong>: <code>approaching-icc.tun.ply.gg</code></li><li><strong>Port</strong>: <code>9256</code></li></ul></li><li>Click <strong>Play</strong> to join!</li></ol><h3 id="method-b-join-through-scholarcraft" tabindex="-1">Method B: Join Through ScholarCraft <a class="header-anchor" href="#method-b-join-through-scholarcraft" aria-label="Permalink to &quot;Method B: Join Through ScholarCraft&quot;">​</a></h3><p>You can also connect to LlamaCraft directly through the <strong>ScholarCraft</strong> server network from Bedrock:</p><ol><li>In your Bedrock <strong>Servers</strong> list, add <strong>ScholarCraft</strong>.</li><li>Connect to ScholarCraft, and use the server selector to jump straight into LlamaCraft!</li></ol><hr><h2 id="_3-consoles-xbox-playstation-nintendo-switch" tabindex="-1">3. Consoles (Xbox, PlayStation, Nintendo Switch) <a class="header-anchor" href="#_3-consoles-xbox-playstation-nintendo-switch" aria-label="Permalink to &quot;3. Consoles (Xbox, PlayStation, Nintendo Switch)&quot;">​</a></h2><p>Consoles don&#39;t have an &quot;Add Server&quot; button by default, but you can join easily using any of these methods:</p><h3 id="method-a-mc-server-connector-app-mobile-lan-bridge" tabindex="-1">Method A: MC Server Connector App (Mobile LAN Bridge) <a class="header-anchor" href="#method-a-mc-server-connector-app-mobile-lan-bridge" aria-label="Permalink to &quot;Method A: MC Server Connector App (Mobile LAN Bridge)&quot;">​</a></h3><ol><li>Download the free app called <strong>MC Server Connector</strong> (or <strong>BedrockTogether</strong>) on your phone.</li><li>Connect your phone to the same home Wi-Fi as your console.</li><li>In the phone app, type IP <code>approaching-icc.tun.ply.gg</code> and Port <code>9256</code>, then tap <strong>Start</strong>.</li><li>On your console, open Minecraft, go to <strong>Friends</strong>, and look under <strong>LAN Games</strong>. Click <code>LlamaCraft</code> to join!</li></ol><h3 id="method-b-bedrockconnect-dns" tabindex="-1">Method B: BedrockConnect DNS <a class="header-anchor" href="#method-b-bedrockconnect-dns" aria-label="Permalink to &quot;Method B: BedrockConnect DNS&quot;">​</a></h3><ol><li>Go to console <strong>Network Settings</strong> &gt; <strong>DNS Settings</strong> &gt; set to <strong>Manual</strong>.</li><li>Set Primary DNS to <code>104.238.130.180</code> and Secondary DNS to <code>1.1.1.1</code>.</li><li>Join any featured server (like The Hive). A custom server menu will appear.</li><li>Select <strong>Connect to a Server</strong>, type <code>approaching-icc.tun.ply.gg</code> and Port <code>9256</code>.</li></ol>',22)])])}const f=e(n,[["render",l]]);export{p as __pageData,f as default};
